package com.gojiramod;

import java.util.HashMap;
import java.util.Map;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.RotatedPillarBlock;
import net.minecraft.world.level.block.state.BlockState;

/**
 * 0.1.5: the giant bone-block skeleton Gojira leaves lying on the sea floor when it dies underwater (layout generated by
 * tools/skeleton.py, see {@link GojiraSkeletonLayout}). Each bone is dropped onto the sea floor below it, and it only
 * ever replaces water, air or seagrass: never stone, sand, or anything someone built.
 */
public final class GojiraSkeleton {
	/** How far below where it died we look for the sea floor (columns with no floor in reach get no bones). */
	public static final int FLOOR_SEARCH = 32;

	private GojiraSkeleton() {
	}

	/** May a bone go here? Only water, air and seagrass. */
	public static boolean canReplace(final BlockState state) {
		return state.isAir() || state.is(Blocks.WATER) || state.is(Blocks.SEAGRASS) || state.is(Blocks.TALL_SEAGRASS);
	}

	/**
	 * Lays the skeleton down on its side: its feet at {@code origin}, its body stretching out the way it {@code fell}, its
	 * snout pointing {@code facing}. Returns how many bone blocks were placed.
	 */
	public static int place(final ServerLevel level, final BlockPos origin, final Direction facing, final Direction fell) {
		int[] bones = GojiraSkeletonLayout.BONES;
		// first find the sea floor under every column (before placing anything, so bones don't stack on each other)
		Map<Long, Integer> floor = new HashMap<>();
		for (int i = 0; i < bones.length; i += 4) {
			BlockPos col = column(origin, facing, fell, bones[i], bones[i + 1]);
			floor.computeIfAbsent(col.asLong(), k -> findFloor(level, col));
		}
		int placed = 0;
		for (int i = 0; i < bones.length; i += 4) {
			BlockPos col = column(origin, facing, fell, bones[i], bones[i + 1]);
			int top = floor.get(col.asLong());
			if (top == Integer.MIN_VALUE) {
				continue; // no sea floor below this bit (a cliff edge, or unloaded): skip it rather than float bones
			}
			BlockPos pos = new BlockPos(col.getX(), top + bones[i + 2], col.getZ());
			if (!level.isInWorldBounds(pos) || !canReplace(level.getBlockState(pos))) {
				continue;
			}
			Direction.Axis axis = switch (bones[i + 3]) {
				case 0 -> fell.getAxis();
				case 1 -> facing.getAxis();
				default -> Direction.Axis.Y;
			};
			level.setBlock(pos, Blocks.BONE_BLOCK.defaultBlockState().setValue(RotatedPillarBlock.AXIS, axis), Block.UPDATE_ALL);
			placed++;
		}
		return placed;
	}

	private static BlockPos column(final BlockPos origin, final Direction facing, final Direction fell, final int a, final int b) {
		return new BlockPos(origin.getX() + a * fell.getStepX() + b * facing.getStepX(), origin.getY(), origin.getZ() + a * fell.getStepZ() + b * facing.getStepZ());
	}

	/** The y of the first spot above solid ground in this column (looking down from a little above where it died). */
	private static int findFloor(final ServerLevel level, final BlockPos col) {
		if (!level.hasChunkAt(col)) {
			return Integer.MIN_VALUE;
		}
		BlockPos.MutableBlockPos p = col.mutable().move(0, 3, 0);
		for (int i = 0; i < FLOOR_SEARCH + 3; i++, p.move(0, -1, 0)) {
			if (!level.isInWorldBounds(p)) {
				return Integer.MIN_VALUE;
			}
			if (!canReplace(level.getBlockState(p))) {
				return i == 0 ? Integer.MIN_VALUE : p.getY() + 1; // buried right from the start: skip
			}
		}
		return Integer.MIN_VALUE;
	}
}
